DROP TABLE IF EXISTS `destinations`;
CREATE TABLE `destinations` (
  `id` varchar(64) NOT NULL,
  `name` varchar(100) NOT NULL,
  `slug` varchar(120) NOT NULL,
  `country` varchar(100) NOT NULL,
  `region` enum('Domestic','International') DEFAULT 'Domestic',
  `tagline` varchar(255) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `cover_image` varchar(512) NOT NULL,
  `gallery_images_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`gallery_images_json`)),
  `best_time_to_visit` varchar(120) DEFAULT NULL,
  `itinerary_count` int(11) DEFAULT 0,
  `starting_price` decimal(10,2) DEFAULT 99.00,
  `is_popular` tinyint(1) DEFAULT 1,
  `is_active` tinyint(1) DEFAULT 1,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `name` (`name`),
  UNIQUE KEY `slug` (`slug`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

