LOCK TABLES `destinations` WRITE;
INSERT INTO `destinations` (`id`, `name`, `slug`, `country`, `region`, `tagline`, `description`, `cover_image`, `gallery_images_json`, `best_time_to_visit`, `itinerary_count`, `starting_price`, `is_popular`, `is_active`, `created_at`, `updated_at`) VALUES
  ('dest-andaman', 'Andaman', 'andaman', 'India', 'Domestic', 'Exotic Coral Diving, Cellular Jail & Radhanagar Beach', 'High-energy tropical island adventure: scuba diving with sea turtles in Nemo Reef, glass-bottom boats to Elephant Beach, and natural rock bridges on Neil Island.', 'https://images.unsplash.com/photo-1544551763-46a013bb70d5?auto=format&fit=crop&w=800&q=80', '["https://images.unsplash.com/photo-1544551763-46a013bb70d5?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1589308078059-be1415eab4c3?auto=format&fit=crop&w=800&q=80"]', 'October to May', 2, '99.00', 1, 1, '2026-09-22 11:31:44', '2026-09-22 11:31:44'),
  ('dest-australia', 'Australia', 'australia', 'Australia', 'International', 'Sydney Opera House, Great Barrier Reef & Gold Coast', 'Experience the iconic beauty of Australia: Sydney Harbour cruises, snorkeling in the Great Barrier Reef, driving the scenic Great Ocean Road, and cuddling koalas.', 'https://images.unsplash.com/photo-1506973035872-a4ec16b8e8d9?auto=format&fit=crop&w=800&q=80', '["https://images.unsplash.com/photo-1506973035872-a4ec16b8e8d9?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1523482580672-f109ba8cb9be?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1529108190281-9a4f620bc2d8?auto=format&fit=crop&w=800&q=80"]', 'September to November & March to May', 2, '99.00', 1, 1, '2026-09-22 11:38:26', '2026-09-22 11:38:26'),
  ('dest-bali', 'Bali', 'bali', 'Indonesia', 'International', 'Tropical Island Escapes, Sacred Waterfalls & Sunsets', 'High-energy 4-day tropical escape highlighting Ubud jungle swings, Tegalalang rice terraces, sacred monkey forest, and Seminyak sunset beach clubs.', 'https://images.unsplash.com/photo-1518548419970-58e3b4079ab2?auto=format&fit=crop&w=800&q=80', '["https://images.unsplash.com/photo-1518548419970-58e3b4079ab2?auto=format&fit=crop&w=800&q=80"]', 'April to October', 2, '99.00', 1, 1, '2026-09-22 11:31:44', '2026-09-22 11:31:44'),
  ('dest-dubai', 'Dubai', 'dubai', 'United Arab Emirates', 'International', 'Ultra-Modern Skylines, Desert Dunes & Mega Malls', 'Ideal 72-hour high-impact Dubai itinerary curated for fast-paced explorers and weekend holiday makers.', 'https://images.unsplash.com/photo-1509316975850-ff9c5deb0cd9?auto=format&fit=crop&w=800&q=80', '["https://images.unsplash.com/photo-1509316975850-ff9c5deb0cd9?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1518684079-3c830dcef090?auto=format&fit=crop&w=800&q=80"]', 'November to April', 3, '99.00', 1, 1, '2026-09-22 11:31:44', '2026-09-22 11:31:44'),
  ('dest-europe', 'Europe', 'europe', 'Switzerland & Austria', 'International', 'Romantic Swiss Alps, Fairytale Cities & Paris Wonders', 'The definitive European postcard holiday. Journey through Zurich, Lucerne, Mount Titlis revolving cable car, scenic Swiss rail across Lauterbrunnen 72 waterfalls, and fairytale lakeside Hallstatt in Austria.', 'https://images.unsplash.com/photo-1530122037265-a5f1f91d3b99?auto=format&fit=crop&w=800&q=80', '["https://images.unsplash.com/photo-1530122037265-a5f1f91d3b99?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1502602898657-3e91760cbb34?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1530122037265-a5f1f91d3b99?auto=format&fit=crop&w=800&q=80"]', 'May to October for alpine lakes, or Dec - Mar for snow ski', 2, '99.00', 1, 1, '2026-09-22 11:31:44', '2026-09-22 11:31:44'),
  ('dest-goa', 'Goa', 'goa', 'India', 'Domestic', 'Sun-Kissed Beaches, Portuguese Quarters & Coastal Nightlife', 'Experience the best of North and South Goa: pristine white sand beaches, UNESCO Portuguese churches, spice plantations, Dudhsagar waterfalls jeep safari, and vibrant beach shacks.', 'https://images.unsplash.com/photo-1512343879784-a960bf40e7f2?auto=format&fit=crop&w=800&q=80', '["https://images.unsplash.com/photo-1512343879784-a960bf40e7f2?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1587922546307-776227941871?auto=format&fit=crop&w=800&q=80"]', 'October to May', 2, '99.00', 1, 1, '2026-09-22 11:31:44', '2026-09-22 11:31:44'),
  ('dest-japan', 'Japan', 'japan', 'Japan', 'International', 'Historic Shrines, Mount Fuji & Neon Shinjuku Lights', 'Experience the cultural soul of Japan: walk beneath ten thousand vermillion torii gates at Fushimi Inari, feed bowing sacred deer in Nara, and eat your way through the neon food paradise of Osaka’s Dotonbori.', 'https://images.unsplash.com/photo-1503899036084-c55cdd92da26?auto=format&fit=crop&w=800&q=80', '["https://images.unsplash.com/photo-1503899036084-c55cdd92da26?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1493976040374-85c8e12f0c0e?auto=format&fit=crop&w=800&q=80"]', 'March to May & September to November', 2, '99.00', 1, 1, '2026-09-22 11:31:44', '2026-09-22 11:31:44'),
  ('dest-kashmir', 'Kashmir', 'kashmir', 'India', 'Domestic', 'Paradise On Earth: Dal Lake Shikaras & Gulmarg Snow', 'A romantic short getaway through Srinagar’s floating markets and Gulmarg’s world-famous Gondola cable car.', 'https://images.unsplash.com/photo-1568889753852-196c487a536e?auto=format&fit=crop&w=800&q=80', '["https://images.unsplash.com/photo-1568889753852-196c487a536e?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1552098933-a5ceb0e5dd91?auto=format&fit=crop&w=800&q=80"]', 'March to October', 2, '99.00', 1, 1, '2026-09-22 11:31:44', '2026-09-22 11:31:44'),
  ('dest-kerala', 'Kerala', 'kerala', 'India', 'Domestic', 'Serene Alleppey Backwaters & Misty Munnar Hills', 'Misty green tea gardens, private treehouse living, bamboo rafting on emerald rivers, and heart-shaped Chembra Lake trek.', 'https://images.unsplash.com/photo-1590050752117-238cb0fb12b1?auto=format&fit=crop&w=800&q=80', '["https://images.unsplash.com/photo-1590050752117-238cb0fb12b1?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1602216056096-3b40cc0c9944?auto=format&fit=crop&w=800&q=80"]', 'September to March', 2, '99.00', 1, 1, '2026-09-22 11:31:44', '2026-09-22 11:31:44'),
  ('dest-ladakh', 'Ladakh', 'ladakh', 'India', 'Domestic', 'High-Altitude Himalayan Passes & Crystal Pangong Lake', 'The quintessential Himalayan high-pass adventure: crossing 17,582 ft Khardung La, riding double-humped Bactrian camels on Nubra sand dunes, and gazing at billions of stars under Bortle 1 skies.', 'https://images.unsplash.com/photo-1544735716-392fe2489ffa?auto=format&fit=crop&w=800&q=80', '["https://images.unsplash.com/photo-1544735716-392fe2489ffa?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1581793745862-99fde7fa73d2?auto=format&fit=crop&w=800&q=80"]', 'May to September', 2, '99.00', 1, 1, '2026-09-22 11:31:44', '2026-09-22 11:31:44'),
  ('dest-maldives', 'Maldives', 'maldives', 'Maldives', 'International', 'Pristine Turquoise Lagoons & Luxury Overwater Villas', 'A dream romantic gateway blueprint designed for honeymooners and beach lovers. Includes seaplane/speedboat logistics, house reef snorkeling spots, private candlelit beach dinner, and overwater bungalow selection guide.', 'https://images.unsplash.com/photo-1514282401047-d79a71a590e8?auto=format&fit=crop&w=800&q=80', '["https://images.unsplash.com/photo-1514282401047-d79a71a590e8?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=800&q=80"]', 'December to April (Dry Season, crystal turquoise water)', 2, '99.00', 1, 1, '2026-09-22 11:31:44', '2026-09-22 11:31:44'),
  ('dest-manali', 'Manali', 'manali', 'India', 'Domestic', 'Rohtang Snow Escapades, Solang Valley & Pine Forests', 'The complete Himachal family road trip: colonial British summer capital Shimla, snowy adventure at Kufri, scenic Beas river valley drive to Manali, Solang Valley paragliding, and Atal Tunnel.', 'https://images.unsplash.com/photo-1571843439991-dd2b8e051966?auto=format&fit=crop&w=800&q=80', '["https://images.unsplash.com/photo-1571843439991-dd2b8e051966?auto=format&fit=crop&w=800&q=80"]', 'Year-round (Snow in Dec - March)', 2, '99.00', 1, 1, '2026-09-22 11:31:44', '2026-09-22 11:31:44'),
  ('dest-rajasthan', 'Rajasthan', 'rajasthan', 'India', 'Domestic', 'Royal Heritage Palaces, Forts & Golden Thar Desert', 'Experience the regal splendor of India’s Desert Kingdom: Jaipur’s Amber Fort & Hawa Mahal, Jodhpur’s impregnable Mehrangarh Fort, and Udaipur’s romantic Lake Pichola boat cruises and grand palaces.', 'https://images.unsplash.com/photo-1599661046289-e31897846e41?auto=format&fit=crop&w=800&q=80', '["https://images.unsplash.com/photo-1599661046289-e31897846e41?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1615836245337-f5b9b2303f10?auto=format&fit=crop&w=800&q=80"]', 'October to March', 2, '99.00', 1, 1, '2026-09-22 11:31:44', '2026-09-22 11:31:44'),
  ('dest-singapore', 'Singapore', 'singapore', 'Singapore', 'International', 'Futuristic Gardens, Marina Bay & Family Attractions', 'Explore the architectural wonder of Gardens by the Bay: the mist-shrouded Cloud Mountain waterfall, 3,000 plant species in Flower Dome, and the nighttime Supertree light symphony.', 'https://images.unsplash.com/photo-1506351421178-63b52a2d2562?auto=format&fit=crop&w=800&q=80', '["https://images.unsplash.com/photo-1506351421178-63b52a2d2562?auto=format&fit=crop&w=800&q=80"]', 'Year-round', 6, '99.00', 1, 1, '2026-09-22 11:31:44', '2026-09-22 11:31:44'),
  ('dest-sri-lanka', 'Sri Lanka', 'sri-lanka', 'Sri Lanka', 'International', 'Lush Tea Plantations, Wildlife Safaris & Golden Coasts', 'Ride the world’s most scenic blue train through misty Ceylon tea plantations, watch steam trains pass the iconic Nine Arch Bridge in Ella, and spot blue whales leaping in the Indian Ocean.', 'https://images.unsplash.com/photo-1546708973-b339540b5162?auto=format&fit=crop&w=800&q=80', '["https://images.unsplash.com/photo-1546708973-b339540b5162?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1586861635167-e5223aadc9fe?auto=format&fit=crop&w=800&q=80"]', 'November to April', 2, '99.00', 1, 1, '2026-09-22 11:31:44', '2026-09-22 11:31:44'),
  ('dest-thailand', 'Thailand', 'thailand', 'Thailand', 'International', 'Vibrant Night Markets, Grand Temples & Island Cruises', 'High-energy 4-day party and sightseeing package covering Pattaya speedboats, parasailing at Koh Larn Coral Island, Bangkok river temples, and bustling night markets.', 'https://images.unsplash.com/photo-1508009603885-50cf7c579365?auto=format&fit=crop&w=800&q=80', '["https://images.unsplash.com/photo-1508009603885-50cf7c579365?auto=format&fit=crop&w=800&q=80"]', 'November to April', 3, '99.00', 1, 1, '2026-09-22 11:31:44', '2026-09-22 11:31:44'),
  ('dest-vietnam', 'Vietnam', 'vietnam', 'Vietnam', 'International', 'Emerald Halong Bay Karsts, Lantern Towns & Street Food', 'The trendiest Vietnam getaway: walk on the giant stone hands of the Golden Bridge in Ba Na Hills, cruise Hoi An lantern-lit canals in a coconut basket boat, and savor authentic egg coffee.', 'https://images.unsplash.com/photo-1559592413-7cec4d0cae2b?auto=format&fit=crop&w=800&q=80', '["https://images.unsplash.com/photo-1559592413-7cec4d0cae2b?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1528127269322-539801943592?auto=format&fit=crop&w=800&q=80"]', 'February to August', 2, '99.00', 1, 1, '2026-09-22 11:31:44', '2026-09-22 11:31:44');
UNLOCK TABLES;

-- ==============================================================================
