DROP TABLE IF EXISTS `travel_agents`;
CREATE TABLE `travel_agents` (
  `id` varchar(64) NOT NULL,
  `agency_name` varchar(160) NOT NULL,
  `founder_name` varchar(120) NOT NULL,
  `gst_number` varchar(40) NOT NULL,
  `phone` varchar(40) NOT NULL,
  `email` varchar(160) NOT NULL,
  `whatsapp` varchar(40) DEFAULT NULL,
  `city` varchar(80) DEFAULT NULL,
  `status` enum('VERIFIED','PENDING_REVIEW','REJECTED') DEFAULT 'VERIFIED',
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `state` varchar(100) DEFAULT NULL,
  `experience_years` varchar(50) DEFAULT NULL,
  `business_type` varchar(50) DEFAULT NULL,
  `specialisations` text DEFAULT NULL,
  `about_agency` text DEFAULT NULL,
  `destinations_sold` text DEFAULT NULL,
  `planned_uploads` varchar(50) DEFAULT NULL,
  `business_proof_name` varchar(255) DEFAULT NULL,
  `business_proof_url` varchar(500) DEFAULT NULL,
  `business_proof_size` int(11) DEFAULT 0,
  `logo_name` varchar(255) DEFAULT NULL,
  `logo_url` varchar(500) DEFAULT NULL,
  `social_link` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `gst_number` (`gst_number`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

