DROP TABLE IF EXISTS `itineraries`;
CREATE TABLE `itineraries` (
  `id` varchar(64) NOT NULL,
  `slug` varchar(120) NOT NULL,
  `destination` varchar(100) NOT NULL,
  `country` varchar(100) NOT NULL,
  `region` varchar(100) NOT NULL,
  `title` varchar(255) NOT NULL,
  `duration_days` int(11) NOT NULL,
  `duration_nights` int(11) NOT NULL,
  `traveler_type` varchar(60) NOT NULL,
  `itinerary_count_label` varchar(60) DEFAULT NULL,
  `access_price` decimal(10,2) DEFAULT 99.00,
  `gst_amount` decimal(10,2) DEFAULT 0.00,
  `total_access_price` decimal(10,2) DEFAULT 99.00,
  `estimated_trip_cost` decimal(12,2) NOT NULL,
  `rating` decimal(3,2) DEFAULT 4.90,
  `review_count` int(11) DEFAULT 0,
  `cover_image` varchar(512) NOT NULL,
  `gallery_images_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`gallery_images_json`)),
  `overview` text DEFAULT NULL,
  `best_time_to_visit` varchar(120) DEFAULT NULL,
  `is_popular` tinyint(1) DEFAULT 0,
  `agent_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`agent_json`)),
  `days_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`days_json`)),
  `hotels_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`hotels_json`)),
  `budget_breakdown_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`budget_breakdown_json`)),
  `inclusions_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`inclusions_json`)),
  `exclusions_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`exclusions_json`)),
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

