  ('andaman-4d', 'havelock-neil-island-scuba-escapade', 'Andaman', 'India', 'Domestic', 'Havelock & Neil Island Escapade: Scuba Diving, Elephant Beach & Natural Coral Bridge', 4, 3, 'Group', '65 Itineraries', '99.00', '0.00', '99.00', '26000.00', '4.93', 104, 'https://images.unsplash.com/photo-1544551763-46a013bb70d5?auto=format&fit=crop&w=800&q=80', '["https://images.unsplash.com/photo-1544551763-46a013bb70d5?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1589308078059-be1415eab4c3?auto=format&fit=crop&w=800&q=80"]', 'High-energy tropical island adventure: scuba diving with sea turtles in Nemo Reef, glass-bottom boats to Elephant Beach, and natural rock bridges on Neil Island.', 'October to May', 0, '{"id":"ag-115","email":"ramesh@blueatoll.in","phone":"+91 94342 88120","rating":4.95,"location":"Port Blair, Andaman","whatsapp":"+91 94342 88120","avatarUrl":"https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=200&q=80","gstNumber":"35AABCB7841N1Z5","agencyName":"Blue Atoll Travel Experts LLP","isVerified":true,"founderName":"Captain Ramesh Varma","reviewCount":420,"yearsInBusiness":12,"itinerariesPublished":38}', '[{"title":"Port Blair to Havelock Island via Makruzz Catamaran","evening":"Sunset walk at Kalapathar Beach with roasted sea snacks.","morning":"Arrive in Port Blair; board Makruzz high-speed AC catamaran to Havelock.","afternoon":"Check into beach resort with private access to turquoise lagoon.","dayNumber":1,"highlights":["Makruzz Catamaran Cruise","Beach Resort Check-in","Kalapathar Sunset"]},{"title":"Scuba Diving at Nemo Reef & Elephant Beach Water Sports","evening":"Seafood barbecue dinner at Barefoot Beach bar.","morning":"PADI-certified beginner scuba dive session among clownfish and live corals.","afternoon":"Speedboat transfer to Elephant Beach for parasailing and sea walk.","dayNumber":2,"highlights":["PADI Scuba Diving","Elephant Beach Parasailing","Seafood BBQ"]},{"title":"Neil Island Day Cruise: Natural Bridge & Laxmanpur Sunset","evening":"Spectacular crimson sunset at Laxmanpur Beach point.","morning":"Ferry to Neil Island (Shaheed Dweep); explore the limestone Natural Rock Bridge.","afternoon":"Swim in calm crystal-clear waters of Bharatpur Beach.","dayNumber":3,"highlights":["Neil Island Natural Bridge","Bharatpur Beach","Laxmanpur Sunset"]},{"title":"Return to Port Blair & Flight Departure","evening":"Flight home with tropical memories.","morning":"Morning cruise back to Port Blair; visit Samudrika Naval Marine Museum.","afternoon":"Airport drop at Veer Savarkar International Airport (IXZ).","dayNumber":4,"highlights":["Marine Museum","Smooth Airport Drop"]}]', '[{"name":"Havelock Country Homes","tier":"Budget","perks":["Pool","Close to Beach"],"rating":4.3,"estPricePerNight":"₹3,000"},{"name":"Symphony Palms Beach Resort / Seashell Havelock","tier":"Comfort","perks":["Private Beach","Breakfast Buffet"],"rating":4.82,"estPricePerNight":"₹8,000"},{"name":"Taj Exotica Resort & Spa, Andamans","tier":"Luxury","perks":["Radhanagar Villa","Luxury Butler","Spa"],"rating":5,"estPricePerNight":"₹38,000"}]', '{"flights":9500,"foodDining":4000,"accommodation":8500,"localTransport":1500,"activitiesSightseeing":2500}', '["Private ferry ticket pre-booking links","PADI dive center direct discount coupon","Island scooter rental contact"]', '["Airfare and accommodation fees","Scuba photo/video raw footage"]', '2026-09-22 19:59:59'),
  ('andaman-5d', 'andaman-island-paradise-port-blair-havelock', 'Andaman', 'India', 'Domestic', 'Andaman Island Paradise: Port Blair Cellular Jail, Havelock Radhanagar & Scuba', 5, 4, 'Couple', '58 Itineraries', '99.00', '0.00', '99.00', '28000.00', '4.92', 98, 'https://images.unsplash.com/photo-1589308078059-be1415eab4c3?auto=format&fit=crop&w=800&q=80', '["https://images.unsplash.com/photo-1589308078059-be1415eab4c3?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=800&q=80"]', 'Discover India’s premier tropical archipelago: historic Cellular Jail light & sound show, high-speed Makruzz catamaran to Havelock Island, sunset at Asia’s best Radhanagar Beach, and PADI certified scuba diving with sea turtles.', 'October to May', 1, '{"id":"ag-116","email":"bookings@andamanholidays.in","phone":"+91 94342 88190","rating":4.9,"location":"Port Blair & Havelock","whatsapp":"+91 94342 88190","avatarUrl":"https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=200&q=80","gstNumber":"35AABCC8920R1Z2","agencyName":"Coral Reef Andaman Holidays LLP","isVerified":true,"founderName":"Kishore Sengupta","reviewCount":280,"yearsInBusiness":11,"itinerariesPublished":26}', '[{"title":"Arrival in Port Blair, Cellular Jail & Light & Sound Show","evening":"Spectacular emotional Light & Sound Show at Cellular Jail; fresh seafood dinner in Port Blair.","morning":"Arrival at Veer Savarkar International Airport Port Blair; transfer to sea-facing hotel.","afternoon":"Tour the historic Cellular Jail (Kala Pani) and learn about India’s freedom struggle.","dayNumber":1,"highlights":["Private Airport Pickup","Historic Cellular Jail","Light & Sound Show"]},{"title":"Makruzz Catamaran to Havelock Island & Radhanagar Beach Sunset","evening":"Watch breathtaking golden sunset over turquoise waves; fresh coconut water and beach stroll.","morning":"Board luxury high-speed Makruzz private catamaran across open azure waters to Havelock Island (Swaraj Dweep).","afternoon":"Check-in to beachfront cottage; head to Radhanagar Beach (Beach No. 7), rated one of Asia’s finest beaches.","dayNumber":2,"highlights":["High-speed Makruzz Catamaran","Radhanagar White Sand Beach","Magical Island Sunset"]},{"title":"Elephant Beach Speedboat, Coral Snorkeling & Scuba Diving","evening":"Candlelight seafood dinner at beach shack with live acoustic guitar.","morning":"Speedboat to Elephant Beach; explore shallow living coral reefs with vibrant clownfish and parrotfish.","afternoon":"PADI-certified beginner introductory scuba diving session with professional underwater HD photos and videos.","dayNumber":3,"highlights":["Elephant Beach Speedboat","Living Coral Snorkeling","PADI Guided Scuba Diving"]},{"title":"Kalapathar Beach, Return to Port Blair & Chidiya Tapu Sunset","evening":"Drive to Chidiya Tapu (Bird Island) for the most magnificent panoramic sunset in the Andamans.","morning":"Visit scenic Kalapathar Beach with black volcanic rocks contrasting against bright turquoise water.","afternoon":"Catamaran cruise back to Port Blair; check into luxury hotel.","dayNumber":4,"highlights":["Kalapathar Volcanic Beach","Return Catamaran Cruise","Chidiya Tapu Sunset Point"]},{"title":"Corbyn’s Cove Beach, Pearl Souvenirs & Departure","evening":"Assisted airport transfer for flight back home.","morning":"Visit Corbyn’s Cove coconut-lined beach; water sports or sea breeze relaxation.","afternoon":"Pick up genuine shell handicrafts, pearl jewelry, and Andaman spices at Sagarika Government Emporium.","dayNumber":5,"highlights":["Corbyn’s Cove Beach","Sagarika Pearl Emporium","Smooth Airport Drop"]}]', '[{"name":"Symphony Palms Havelock / Peerless Port Blair","tier":"Budget","perks":["Direct Beach Access","Free Wi-Fi"],"rating":4.4,"estPricePerNight":"₹3,500"},{"name":"Barefoot at Havelock / SeaShell Port Blair","tier":"Comfort","perks":["Eco Jungle Cottages","Private Beach Access","Buffet"],"rating":4.85,"estPricePerNight":"₹10,500"},{"name":"Taj Exotica Resort & Spa Andamans","tier":"Luxury","perks":["Radhanagar Private Villa","Olympic Infinity Pool","Butler"],"rating":4.98,"estPricePerNight":"₹38,000"}]', '{"flights":11000,"foodDining":3500,"accommodation":9000,"localTransport":1500,"activitiesSightseeing":3000}', '["Makruzz private catamaran seat class comparison and booking strategy","Scuba dive operator PADI certification verification guide","Island permit and luggage transfer logistics"]', '["Airfare and accommodation fees","Personal scuba video packages"]', '2026-09-21 22:15:18'),
  ('australia-5d', 'melbourne-great-ocean-road-12-apostles-5d', 'Australia', 'Australia', 'International', 'Melbourne, Great Ocean Road & Phillip Island: 12 Apostles & Little Penguin Parade', 5, 4, 'Couple', '42 Itineraries', '99.00', '0.00', '99.00', '95000.00', '4.94', 184, 'https://images.unsplash.com/photo-1523482580672-f109ba8cb9be?auto=format&fit=crop&w=800&q=80', '["https://images.unsplash.com/photo-1523482580672-f109ba8cb9be?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1506973035872-a4ec16b8e8d9?auto=format&fit=crop&w=800&q=80"]', 'The classic southeastern Australian holiday: world-class coffee in Melbourne laneways, dramatic coastal cliffs along Great Ocean Road, and fairy penguins on Phillip Island.', 'October to April', 0, '{"id":"ag-118","agencyName":"Aussie Horizons Travel Pvt Ltd","founderName":"Marcus Hemsworth","gstNumber":"27AAACH9102K1ZP","phone":"+91 98204 77192","email":"bookings@aussiehorizons.com","whatsapp":"+91 98204 77192","location":"Mumbai & Sydney","rating":4.96,"reviewCount":380,"yearsInBusiness":11,"itinerariesPublished":24,"isVerified":true,"avatarUrl":"https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=200&q=80"}', '[{"dayNumber":1,"title":"Arrival in Melbourne & Laneways Street Art Tour","morning":"Arrive at Melbourne Airport (MEL); transfer to Flinders Street cultural quarter.","afternoon":"Guided walking tour through Hosier Lane graffiti murals, Degraves Street cafes, and Royal Arcade.","evening":"Yarra River night stroll with drinks at Ponyfish Island floating bar.","highlights":["Hosier Lane Murals","Degraves Coffee Walk","Yarra River Nightline"]},{"dayNumber":2,"title":"Great Ocean Road & 12 Apostles Sunset Drive","morning":"Full-day coastal road trip along the legendary Great Ocean Road via Torquay and Lorne surf beaches.","afternoon":"Spot wild koalas in eucalyptus trees at Kennett River; walk through ancient Maits Rest rainforest.","evening":"Watch the sunset over the dramatic limestone limestone stacks of the 12 Apostles and Loch Ard Gorge.","highlights":["12 Apostles Sunset","Kennett River Koalas","Loch Ard Gorge"]},{"dayNumber":3,"title":"Yarra Valley Wine Tasting & Healesville Sanctuary","morning":"Scenic vineyard drive into the rolling green Yarra Valley; wine tasting at Domaine Chandon.","afternoon":"Encounter Australian dingoes, wombats, and platypuses at Healesville Wildlife Sanctuary.","evening":"Artisanal cheese tasting and gourmet farm dinner in Yarra Glen.","highlights":["Domaine Chandon Cellar","Healesville Wildlife","Yarra Farm Dinner"]},{"dayNumber":4,"title":"Phillip Island Little Penguin Parade","morning":"Morning leisure shopping at Queen Victoria Market; visit St Kilda beach and Luna Park.","afternoon":"Scenic drive to Phillip Island; walk along Nobbies boardwalk watching fur seals.","evening":"Witness hundreds of wild fairy penguins waddle up the beach at sunset during the world-famous Penguin Parade.","highlights":["Philip Island Penguin Parade","Nobbies Boardwalk Seals","Queen Victoria Market"]},{"dayNumber":5,"title":"Brighton Bathing Boxes & Flight Departure","morning":"Iconic photo stop at colorful Brighton Bathing Boxes overlooking Port Phillip Bay.","afternoon":"Last-minute boutique shopping in South Yarra and transfer to Melbourne Airport (MEL).","evening":"Board flight back home with extraordinary Australian memories.","highlights":["Brighton Bathing Boxes","South Yarra Boutiques","Smooth Airport Drop"]}]', '[{"name":"Rendezvous Hotel Melbourne","tier":"Budget","estPricePerNight":"₹6,800","perks":["Heritage Charm","Central"],"rating":4.3},{"name":"Crown Metropol Melbourne / Vibe Hotel","tier":"Comfort","estPricePerNight":"₹13,500","perks":["Sky Pool","City Views","Yarra Walk"],"rating":4.88},{"name":"The Langham Melbourne","tier":"Luxury","estPricePerNight":"₹28,000","perks":["Chuan Spa","Yarra River Panorama","Afternoon Tea"],"rating":4.96}]', '{"flights":38000,"accommodation":24000,"foodDining":12000,"localTransport":7000,"activitiesSightseeing":14000}', '["Great Ocean Road reverse tour self-drive GPS waypoint map","Phillip Island penguin parade reserved grandstand seating ticket links","Melbourne laneway coffee map and curated foodie recommendations"]', '["Car rental fuel and toll road charges","International flights and tourist visas"]', '2026-09-22 11:38:39'),
  ('australia-6d', 'sydney-great-barrier-reef-cairns-6d', 'Australia', 'Australia', 'International', 'Iconic Sydney & Great Barrier Reef: Opera House, Bondi Beach & Cairns Catamaran Snorkel', 6, 5, 'Family', '42 Itineraries', '99.00', '0.00', '99.00', '108000.00', '4.96', 218, 'https://images.unsplash.com/photo-1506973035872-a4ec16b8e8d9?auto=format&fit=crop&w=800&q=80', '["https://images.unsplash.com/photo-1506973035872-a4ec16b8e8d9?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1523482580672-f109ba8cb9be?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1529108190281-9a4f620bc2d8?auto=format&fit=crop&w=800&q=80"]', 'The ultimate Australian bucket-list journey: witness sunset over Sydney Opera House, walk Bondi cliff paths, ride through Blue Mountains rainforests, and dive into the Great Barrier Reef.', 'September to November & March to May', 1, '{"id":"ag-118","agencyName":"Aussie Horizons Travel Pvt Ltd","founderName":"Marcus Hemsworth","gstNumber":"27AAACH9102K1ZP","phone":"+91 98204 77192","email":"bookings@aussiehorizons.com","whatsapp":"+91 98204 77192","location":"Mumbai & Sydney","rating":4.96,"reviewCount":380,"yearsInBusiness":11,"itinerariesPublished":24,"isVerified":true,"avatarUrl":"https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=200&q=80"}', '[{"dayNumber":1,"title":"Arrival in Sydney, Circular Quay & Opera House Sunset","morning":"Arrive at Sydney Kingsford Smith Airport (SYD); scenic transfer to Darling Harbour hotel.","afternoon":"Stroll around Circular Quay, The Rocks historical cobblestone laneways, and Opera House forecourt.","evening":"Sunset catamaran dinner cruise across Sydney Harbour passing beneath Harbour Bridge.","highlights":["Circular Quay Walk","The Rocks Historic Precinct","Harbour Sunset Cruise"]},{"dayNumber":2,"title":"Bondi Beach Coastal Walk & Taronga Zoo Ferry","morning":"Scenic Bondi to Coogee cliffside coastal ocean walk with swim in Bondi Icebergs.","afternoon":"Yellow Water Taxi to Taronga Zoo with panoramic skyline vistas and native koala encounters.","evening":"Craft dining and craft beer tasting at Barangaroo waterfront promenade.","highlights":["Bondi to Coogee Walk","Taronga Zoo Koalas","Barangaroo Dining"]},{"dayNumber":3,"title":"Blue Mountains Day Trip: Three Sisters & Scenic World","morning":"Scenic rail to Katoomba; visit Echo Point overlooking the legendary Three Sisters rock formation.","afternoon":"Ride Scenic Railway (world steepest passenger train) and cableway down into ancient Jurassic rainforest.","evening":"Stargazing dinner at Leura mountain village before returning to Sydney.","highlights":["Three Sisters Echo Point","Scenic Railway Steep Descent","Jamison Valley Rainforest"]},{"dayNumber":4,"title":"Flight to Cairns: Gateway to Great Barrier Reef","morning":"Morning domestic flight from Sydney to tropical Cairns (Queensland).","afternoon":"Check in to beachfront resort; visit Cairns Esplanade Lagoon and Night Markets.","evening":"Fresh Queensland tiger prawn and barramundi seafood dinner along Cairns boardwalk.","highlights":["Cairns Lagoon Swim","Tropical Boardwalk","Fresh Barramundi Feast"]},{"dayNumber":5,"title":"Outer Great Barrier Reef Catamaran & Coral Snorkeling","morning":"Board luxury high-speed catamaran to Moore Reef Outer Pontoon.","afternoon":"Guided marine biologist snorkeling among sea turtles, clownfish, and semi-submersible coral viewing.","evening":"Tropical buffet lunch on reef pontoon; evening return to Cairns.","highlights":["Moore Reef Outer Barrier","Marine Biologist Snorkel","Semi-Sub Coral Explorer"]},{"dayNumber":6,"title":"Kuranda Rainforest Skyrail & Departure","morning":"Glide above rainforest canopy on Skyrail Rainforest Cableway to Kuranda artisan village.","afternoon":"Scenic Kuranda Railway ride passing Barron Falls gorges back to Cairns Airport (CNS).","evening":"Flight departure with lifelong Australian memories.","highlights":["Skyrail Rainforest Canopy","Barron Falls Gorges","Kuranda Village"]}]', '[{"name":"Ibis Styles Sydney Central","tier":"Budget","estPricePerNight":"₹6,500","perks":["Central Location","Free WiFi"],"rating":4.2},{"name":"Hyatt Regency Sydney / Cairns Pacific Hotel","tier":"Comfort","estPricePerNight":"₹14,500","perks":["Harbour Views","Buffet Breakfast","Pool"],"rating":4.85},{"name":"Four Seasons Hotel Sydney / Crystalbrook Riley","tier":"Luxury","estPricePerNight":"₹32,000","perks":["Opera House Panorama","Luxury Butler","Infinity Pool"],"rating":4.95}]', '{"flights":42000,"accommodation":28000,"foodDining":14000,"localTransport":8000,"activitiesSightseeing":16000}', '["Catamaran Moore Reef outer pontoon day cruise voucher","Sydney Harbour ferry pass and Opal card pre-setup guide","Verified local Australian tour operator direct contacts"]', '["International and domestic airfares","Personal scuba certification fees"]', '2026-09-22 11:38:26'),
  ('bali-4d', 'bali-express-ubud-rice-terraces-beach-clubs', 'Bali', 'Indonesia', 'International', 'Bali Express: Ubud Waterfalls, Rice Terraces & Seminyak Beach Clubs', 4, 3, 'Solo', '64 Itineraries', '99.00', '0.00', '99.00', '29000.00', '4.88', 84, 'https://images.unsplash.com/photo-1518548419970-58e3b4079ab2?auto=format&fit=crop&w=800&q=80', '["https://images.unsplash.com/photo-1518548419970-58e3b4079ab2?auto=format&fit=crop&w=800&q=80"]', 'High-energy 4-day tropical escape highlighting Ubud jungle swings, Tegalalang rice terraces, sacred monkey forest, and Seminyak sunset beach clubs.', 'April to October', 0, '{"id":"ag-104","email":"bali@nusantaraholidays.com","phone":"+91 97240 88210","rating":4.9,"location":"Ahmedabad & Denpasar Bali","whatsapp":"+91 97240 88210","avatarUrl":"https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?auto=format&fit=crop&w=200&q=80","gstNumber":"24AAACN9921B1Z4","agencyName":"Nusantara Island Holidays Pvt Ltd","isVerified":true,"founderName":"Ketut Astawa","reviewCount":310,"yearsInBusiness":12,"itinerariesPublished":38}', '[{"title":"Arrival in Denpasar, Private Transfer to Ubud & Jungle Cafe","evening":"Walk through Ubud traditional art market and dine at organic cafe overlooking the jungle canopy.","morning":"Land at Ngurah Rai Airport (DPS); private AC car transfer through Balinese stone carving villages to Ubud.","afternoon":"Check into rainforest pool villa; enjoy tropical coconut welcome drink.","dayNumber":1,"highlights":["Private Airport Pickup","Rainforest Villa Check-in","Ubud Art Market Walk"]},{"title":"Tegalalang Rice Terraces, Jungle Swing & Tirta Empul","evening":"Dinner in Ubud center accompanied by a traditional Legong dance performance.","morning":"Early 7 AM visit to Tegalalang rice terraces before crowds; ride the famous Bali valley swing.","afternoon":"Visit holy water temple of Tirta Empul for traditional Balinese cleansing blessing.","dayNumber":2,"highlights":["Tegalalang Rice Terraces","Bali Valley Swing","Tirta Empul Holy Spring"]},{"title":"Ubud to Seminyak: Tegenungan Waterfall & Potato Head Sunset","evening":"VIP daybed entry at Potato Head Beach Club; cocktail sunset over the Indian Ocean.","morning":"Scenic stop at Tegenungan Waterfall and dip in freshwater pool.","afternoon":"Drive to southern Bali coast (Seminyak); check into stylish beach hotel.","dayNumber":3,"highlights":["Tegenungan Waterfall","Seminyak Boutique Stroll","Potato Head Beach Sunset"]},{"title":"Uluwatu Clifftop Temple & Airport Departure","evening":"Private airport transfer to DPS for evening return flight.","morning":"Surf or relax on Seminyak beach; indulge in Balinese aromatherapy massage.","afternoon":"Visit breathtaking Uluwatu clifftop temple perched 70 meters above crashing waves.","dayNumber":4,"highlights":["Balinese Aromatherapy Spa","Uluwatu Ocean Cliff","Seamless Airport Drop"]}]', '[{"name":"Pertiwi Bisma Ubud","tier":"Budget","perks":["Rice Field View","Infinity Pool"],"rating":4.5,"estPricePerNight":"₹3,500"},{"name":"Maya Ubud Resort & Spa","tier":"Comfort","perks":["River Valley","Free Yoga Classes"],"rating":4.8,"estPricePerNight":"₹9,500"},{"name":"Alila Seminyak","tier":"Luxury","perks":["Direct Beachfront","Sunset Bar"],"rating":4.95,"estPricePerNight":"₹26,000"}]', '{"flights":17000,"foodDining":3000,"accommodation":6000,"localTransport":1000,"activitiesSightseeing":2000}', '["Smart 4-day route optimized to avoid southern Bali traffic bottlenecks","VIP beach club daybed booking tips","SIM card and scooter rental guidance"]', '["Airfare and accommodation tariffs","Personal dining and club tabs"]', '2026-09-21 22:15:18'),
  ('bali-5d', 'bali-ubud-temples-seminyak-beaches-nusa-penida', 'Bali', 'Indonesia', 'International', 'Tropical Bali Magic: Ubud Rice Terraces, Nusa Penida & Uluwatu Sunset', 5, 4, 'Couple', '64 Itineraries', '99.00', '0.00', '99.00', '38000.00', '4.92', 64, 'https://images.unsplash.com/photo-1537996194471-e657df975ab4?auto=format&fit=crop&w=800&q=80', '["https://images.unsplash.com/photo-1537996194471-e657df975ab4?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1518548419970-58e3b4079ab2?auto=format&fit=crop&w=800&q=80"]', 'Immerse yourself in the Island of the Gods: emerald Tegalalang rice terraces in Ubud, thrilling jungle swings, sacred water temples, speed boat excursion to Nusa Penida’s Kelingking T-Rex cliff, and Uluwatu cliff sunset with Kecak fire dance.', 'April to October (Dry season, golden sunshine)', 1, '{"id":"ag-106","email":"bali@nusantaraglobal.com","phone":"+91 98470 22390","rating":4.9,"location":"Kochi & Denpasar","whatsapp":"+91 98470 22390","avatarUrl":"https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?auto=format&fit=crop&w=200&q=80","gstNumber":"32AABCN5540M1Z2","agencyName":"Nusantara Global Tours Pvt Ltd","isVerified":true,"founderName":"Ketut Wijaya & Rahul Nair","reviewCount":290,"yearsInBusiness":10,"itinerariesPublished":38}', '[{"title":"Arrival in Denpasar (DPS), Transfer to Cultural Ubud & Sacred Monkey Forest","evening":"Explore Ubud Art Market for bamboo straw bags and batik; dinner at Bebek Bengil (famous crispy duck restaurant).","morning":"Arrive at Ngurah Rai International Airport; meet private English-speaking Balinese driver; scenic drive through artisan villages to Ubud.","afternoon":"Hotel check-in to jungle-view villa; stroll through Sacred Monkey Forest Sanctuary with hundreds of playful Balinese macaques.","dayNumber":1,"highlights":["Private Balinese Chauffeur","Sacred Monkey Forest","Authentic Ubud Art Market"]},{"title":"Tegalalang Rice Terraces, Aloha Jungle Swing & Tirta Empul Holy Water","evening":"Sip Luwak coffee at scenic spice plantation; dinner in Ubud overlooking illuminated rainforest ravines.","morning":"Sunrise photo shoot at emerald Tegalalang Rice Terraces; fly over jungle valley on iconic giant Bali Swing.","afternoon":"Visit Tirta Empul Temple; take part in traditional Balinese Melukat holy water cleansing purification ritual.","dayNumber":2,"highlights":["Tegalalang Rice Paddies","Giant Jungle Swing","Holy Water Purification Ritual"]},{"title":"Speedboat to Nusa Penida Island: Kelingking T-Rex Cliff & Broken Beach","evening":"Speedboat return to main island; transfer to trendy beachfront hotel in Seminyak or Canggu.","morning":"Early morning speedboat from Sanur port to rugged Nusa Penida island.","afternoon":"Marvel at jaw-dropping Kelingking T-Rex shaped cliff towering over turquoise ocean; visit Angel’s Billabong natural infinity pool and Broken Beach.","dayNumber":3,"highlights":["Kelingking T-Rex Cliff","Angel’s Billabong Pool","Seminyak Beachfront Sunset"]},{"title":"Seminyak Beach Clubs, Uluwatu Cliff Temple & Sunset Kecak Fire Dance","evening":"Watch hypnotic Kecak Fire Dance performed against dramatic Indian Ocean sunset backdrop; seafood BBQ dinner on Jimbaran Bay sands.","morning":"Relaxed morning at Seminyak or Canggu; surf lesson or chill at beachfront club like Potato Head or Café del Mar.","afternoon":"Drive along Bukit Peninsula; visit ancient Uluwatu Temple perched 70 meters high on a sheer limestone ocean cliff.","dayNumber":4,"highlights":["Potato Head Beach Club","Uluwatu Cliff Temple","Kecak Fire Dance & Jimbaran BBQ"]},{"title":"Tanah Lot Water Temple, Souvenir Shopping & Denpasar Departure","evening":"Transfer to Denpasar airport for homeward flight.","morning":"Visit iconic Tanah Lot Temple resting on an offshore rock formation wrapped in ocean waves.","afternoon":"Last-minute shopping at Krisna Oleh Oleh for authentic Balinese coffee and handmade soaps; packing & checkout.","dayNumber":5,"highlights":["Tanah Lot Rock Temple","Krisna Oleh Souvenir Hub","Seamless Airport Drop"]}]', '[{"name":"Komaneka at Rasa Sayang Ubud / Fairfield by Marriott Seminyak","tier":"Budget","perks":["Swimming Pool","Tropical Garden","Free Wi-Fi"],"rating":4.4,"estPricePerNight":"₹3,500 - ₹5,500"},{"name":"Padma Resort Ubud / W Bali Seminyak","tier":"Comfort","perks":["Heated Infinity Pool","Beachfront Club","Luxury Spa"],"rating":4.8,"estPricePerNight":"₹14,000 - ₹24,000"},{"name":"Viceroy Bali / Bulgari Resort Bali","tier":"Luxury","perks":["Valley Villa with Pool","Helipad Access","Private Ocean Butler"],"rating":5,"estPricePerNight":"₹48,000 - ₹95,000"}]', '{"flights":21000,"foodDining":5000,"accommodation":10000,"localTransport":3000,"activitiesSightseeing":5000}', '["Day-by-day GPS coordinates for photo spots and hidden beaches","Driver tipping guidance and money exchange security tips","Direct WhatsApp and emergency line to verified Bali agency founder","Nusa Penida boat timing and sea-sickness prevention advisory"]', '["Indonesia Visa on Arrival (USD 35 / ~₹2,900 payable at airport or online)","Bali Tourist Levy (IDR 150,000 / ~₹800)"]', '2026-09-21 22:15:18'),
