  ('europe-7d', 'europe-swiss-alps-hallstatt-paris-highlights', 'Europe', 'Switzerland & Austria', 'International', 'Dream Europe Alpine Odyssey: Swiss Alps, Lucerne & Fairytale Hallstatt', 7, 6, 'Couple', '210 Itineraries', '99.00', '0.00', '99.00', '145000.00', '4.98', 210, 'https://images.unsplash.com/photo-1530122037265-a5f1f91d3b99?auto=format&fit=crop&w=800&q=80', '["https://images.unsplash.com/photo-1530122037265-a5f1f91d3b99?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1502602898657-3e91760cbb34?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1530122037265-a5f1f91d3b99?auto=format&fit=crop&w=800&q=80"]', 'The definitive European postcard holiday. Journey through Zurich, Lucerne, Mount Titlis revolving cable car, scenic Swiss rail across Lauterbrunnen 72 waterfalls, and fairytale lakeside Hallstatt in Austria.', 'May to October for alpine lakes, or Dec - Mar for snow ski', 1, '{"id":"ag-105","email":"concierge@eurovistas.com","phone":"+91 98300 77123","rating":4.95,"location":"Kolkata & Zurich","whatsapp":"+91 98300 77123","avatarUrl":"https://images.unsplash.com/photo-1580489944761-15a19d654956?auto=format&fit=crop&w=200&q=80","gstNumber":"19AAACE4910Q1Z7","agencyName":"EuroVistas Tours & Travels Pvt Ltd","isVerified":true,"founderName":"Ananya Sengupta","reviewCount":512,"yearsInBusiness":16,"itinerariesPublished":88}', '[{"title":"Arrival in Zurich, Swiss Travel Pass Activation & Lucerne Lake Cruise","evening":"Scenic paddle-steamer cruise on Lake Lucerne with snow-dusted peaks in background; Swiss cheese fondue dinner.","morning":"Arrive at Zurich Airport (ZRH); validate 4-Day First-Class Swiss Travel Pass; train to romantic Lucerne (50 mins).","afternoon":"Stroll across 14th-century wooden Chapel Bridge (Kapellbrücke) and poignant Lion Monument.","dayNumber":1,"highlights":["First-Class Swiss Train","Historic Chapel Bridge","Lake Lucerne Steamer Cruise"]},{"title":"Mount Titlis Rotair Revolving Cable Car & Glacier Cliff Walk","evening":"Return to Lucerne; lakeside evening walk; Swiss artisan chocolate shopping at Läderach.","morning":"Train to Engelberg; board world-first revolving Titlis Rotair cable car ascending to 3,020 meters above sea level.","afternoon":"Walk across Titlis Cliff Walk (Europe’s highest suspension footbridge); explore magical deep blue Glacier Cave.","dayNumber":2,"highlights":["Titlis Rotair Cable Car","Cliff Suspension Bridge","Läderach Chocolate Tasting"]},{"title":"Interlaken, Lauterbrunnen Valley of 72 Waterfalls & Grindelwald First","evening":"Cozy dinner in chalet village of Grindelwald with views of majestic Eiger North Face.","morning":"GoldenPass train from Lucerne over Brünig Pass to Interlaken and fairytale Lauterbrunnen valley.","afternoon":"Hike past roaring Staubbach Fall; cable car to Grindelwald-First for First Cliff Walk by Tissot.","dayNumber":3,"highlights":["Lauterbrunnen Valley","Staubbach Waterfalls","Grindelwald First Cliff Walk"]},{"title":"Jungfraujoch – Top of Europe & Aletsch Glacier Ice Palace","evening":"Scenic train descent via Wengen; return to Zurich for overnight stay in city center.","morning":"Board high-tech Eiger Express tricable gondola up to Jungfraujoch (3,454m), highest train station in Europe.","afternoon":"Step onto Sphinx Observatory deck overlooking great Aletsch Glacier (UNESCO World Heritage); wander Ice Palace sculptures.","dayNumber":4,"highlights":["Eiger Express Tricable Gondola","Sphinx Observatory","Aletsch Glacier Ice Palace"]},{"title":"Scenic ÖBB Rail to Salzburg & Fairytale Hallstatt Lake Village","evening":"Lakeside dinner overlooking tranquil swans and mirror reflections of Austrian wooden timber homes.","morning":"Comfortable rail journey crossing into Austria; arrive in breathtaking Salzkammergut Lake District.","afternoon":"Arrive in world-famous fairytale Hallstatt; stroll ancient cobblestone market square and 7,000-year-old salt mine.","dayNumber":5,"highlights":["Salzkammergut Lake District","Hallstatt Market Square","World Oldest Salt Mine"]},{"title":"Salzburg Sound of Music Landmarks & Mirabell Gardens","evening":"Classical Mozart evening concert at fortress hall with panoramic city views.","morning":"Short transfer to Mozart’s birthplace, Salzburg; explore Hohensalzburg Fortress high above baroque old town.","afternoon":"Walk through Mirabell Gardens and Palace (filming spot for Do-Re-Mi); explore Getreidegasse boutique street.","dayNumber":6,"highlights":["Hohensalzburg Fortress","Mirabell Gardens","Mozart Birthplace & Concert"]},{"title":"Vienna Panorama, Schönbrunn Palace & Flight Departure","evening":"Vienna International Airport (VIE) departure for flight back home.","morning":"High-speed Railjet to Vienna; marvel at imperial Schönbrunn Palace and lavish Habsburg gardens.","afternoon":"Enjoy authentic Viennese coffee and Sachertorte chocolate cake at historic Café Central.","dayNumber":7,"highlights":["Schönbrunn Imperial Palace","Café Central Sachertorte","Direct Airport Express"]}]', '[{"name":"Ibis Styles Lucerne / Meininger Salzburg","tier":"Budget","perks":["Walking to Main Station","Free Wi-Fi","Continental Breakfast"],"rating":4.4,"estPricePerNight":"₹9,000 - ₹12,000"},{"name":"Hotel des Balances Lucerne / Heritage Hotel Hallstatt","tier":"Comfort","perks":["Balcony Lake Views","Historic Boutique Charms","Gourmet Dining"],"rating":4.8,"estPricePerNight":"₹22,000 - ₹35,000"},{"name":"Victoria-Jungfrau Interlaken / Sacher Salzburg","tier":"Luxury","perks":["Spa & Thermal Bath","World Famous Sacher Hotel","Five-Star Butler"],"rating":5,"estPricePerNight":"₹65,000 - ₹1,20,000"}]', '{"flights":55000,"foodDining":22000,"accommodation":48000,"localTransport":16000,"activitiesSightseeing":14000}', '["Complete Swiss Travel Pass vs Point-to-point ticket optimization strategy","Schengen Visa appointment booking guide & document checklist template","Step-by-step train platform numbers and transfer timings guide","Direct WhatsApp and emergency 