perks":["Walking to Beach","Outdoor Pool"],"rating":4.4,"estPricePerNight":"₹2,800"},{"name":"Amari Phuket / Centara Grand Beach Resort Krabi","tier":"Comfort","perks":["Private Beach Cove","Cliffside Spa","Buffet"],"rating":4.8,"estPricePerNight":"₹8,500"},{"name":"Rayavadee Krabi / Sri Panwa Phuket","tier":"Luxury","perks":["Private Pavilion Pool","Grotto Dining","Helipad"],"rating":4.98,"estPricePerNight":"₹38,000"}]', '{"flights":18000,"foodDining":4500,"accommodation":10000,"localTransport":1500,"activitiesSightseeing":4000}', '["Phuket to Krabi ferry fast-track ticket voucher codes","Maya Bay environmental fee and entry timing advisory","Direct WhatsApp emergency line for Andaman boat transfers"]', '["Thailand Tourist Visa fees","Phang Nga National Park fee (THB 400)"]', '2026-09-21 22:15:18'),
  ('vietnam-5d', 'central-vietnam-danang-hoian-golden-bridge', 'Vietnam', 'Vietnam', 'International', 'Central Vietnam Highlights: Da Nang Golden Bridge, Hoi An Lanterns & Marble Mountains', 5, 4, 'Couple', '82 Itineraries', '99.00', '0.00', '99.00', '32000.00', '4.96', 154, 'https://images.unsplash.com/photo-1559592413-7cec4d0cae2b?auto=format&fit=crop&w=800&q=80', '["https://images.unsplash.com/photo-1559592413-7cec4d0cae2b?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1528127269322-539801943592?auto=format&fit=crop&w=800&q=80"]', 'The trendiest Vietnam getaway: walk on the giant stone hands of the Golden Bridge in Ba Na Hills, cruise Hoi An lantern-lit canals in a coconut basket boat, and savor authentic egg coffee.', 'February to August', 0, '{"id":"ag-113","email":"somchai@siamdiscovery.in","phone":"+91 98200 44102","rating":4.92,"location":"Mumbai & Bangkok","whatsapp":"+91 98200 44102","avatarUrl":"https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=200&q=80","gstNumber":"27AABCS7712M1Z8","agencyName":"Siam Discovery Travel Pvt Ltd","isVerified":true,"founderName":"Somchai Prasert","reviewCount":520,"yearsInBusiness":14,"itinerariesPublished":44}', '[{"title":"Arrival in Da Nang & Dragon Bridge Fire Show","evening":"Watch the Dragon Bridge breathe fire and water; dinner at night seafood market.","morning":"Arrive at Da Nang International Airport (DAD); check into beachfront hotel on My Khe Beach.","afternoon":"Relax on the sands of My Khe Beach; Vietnamese iced coffee at local cafe.","dayNumber":1,"highlights":["My Khe Beach","Dragon Bridge Fire Show","Seafood Night Market"]},{"title":"Ba Na Hills & Iconic Golden Hands Bridge","evening":"Explore French Village and wine cellars before descending back to Da Nang.","morning":"Ride world record cable car to Sun World Ba Na Hills.","afternoon":"Walk across the world-famous Golden Bridge held aloft by colossal stone hands.","dayNumber":2,"highlights":["Golden Hands Bridge Walk","Ba Na Hills Cable Car","French Village"]},{"title":"Marble Mountains & Hoi An Ancient Lantern Town","evening":"Release glowing paper lanterns into Thu Bon River; authentic Cao Lau noodle dinner.","morning":"Explore Buddhist caves and stone carving village at Marble Mountains.","afternoon":"Transfer to UNESCO World Heritage Hoi An Ancient Town; tailor-made suit shopping.","dayNumber":3,"highlights":["Marble Mountains Caves","Hoi An Ancient Streets","Floating River Lanterns"]},{"title":"Bay Mau Coconut Forest Basket Boat Ride","evening":"Night stroll through night market illuminated by thousands of silk lanterns.","morning":"Traditional spinning round bamboo basket boat ride through mangrove waterways.","afternoon":"Cooking class learning Vietnamese spring rolls and Banh Xeo pancakes.","dayNumber":4,"highlights":["Coconut Basket Boat","Vietnamese Cooking Class","Silk Lantern Night Market"]},{"title":"Departure from Da Nang","evening":"Flight home.","morning":"Last bowl of Pho Bo breakfast; souvenir coffee and pepper shopping.","afternoon":"Transfer to Da Nang Airport for flight home.","dayNumber":5,"highlights":["Pho Breakfast","Smooth Departure"]}]', '[{"name":"Haian Riverfront Hotel Da Nang","tier":"Budget","perks":["Rooftop Pool","Breakfast"],"rating":4.4,"estPricePerNight":"₹2,800"},{"name":"La Siesta Hoi An Resort & Spa","tier":"Comfort","perks":["Saltwater Pool","Rice Field View","Spa"],"rating":4.9,"estPricePerNight":"₹6,500"},{"name":"InterContinental Danang Sun Peninsula Resort","tier":"Luxury","perks":["Private Bay","Bill Bensley Design","Michelin Dining"],"rating":5,"estPricePerNight":"₹34,000"}]', '{"flights":11000,"foodDining":5000,"accommodation":9500,"localTransport":2500,"activitiesSightseeing":4000}', '["Ba Na Hills express cable car e-ticket tips","Hoi An custom tailoring best shops list","Vietnam E-visa fast-track step by step"]', '["Airfare and accommodation fees","Tailor garments"]', '2026-09-22 19:59:59'),
  ('vietnam-6d', 'enchanting-vietnam-hanoi-halong-bay-hoi-an', 'Vietnam', 'Vietnam', 'International', 'Enchanting Vietnam: Hanoi Old Quarter, Halong Bay Cruise & Hoi An Lanterns', 6, 5, 'Couple', '72 Itineraries', '99.00', '0.00', '99.00', '44000.00', '4.95', 110, 'https://images.unsplash.com/photo-1528127269322-539801943592?auto=format&fit=crop&w=800&q=80', '["https://images.unsplash.com/photo-1528127269322-539801943592?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1509042239860-f550ce710b93?auto=format&fit=crop&w=800&q=80"]', 'Discover the magic of Southeast Asia: bustling French colonial streets of Hanoi, luxury overnight cruise through UNESCO limestone karsts of Halong Bay, and fairytale glowing lanterns of UNESCO ancient town Hoi An.', 'October to April', 1, '{"id":"ag-114","email":"vietnam@indochinatrails.com","phone":"+91 98110 88219","rating":4.93,"location":"Delhi & Hanoi","whatsapp":"+91 98110 88219","avatarUrl":"https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=200&q=80","gstNumber":"07AABCI4412M1Z0","agencyName":"Indochina Trails & Voyages Ltd","isVerified":true,"founderName":"Nguyen Van Minh & Ankit Agarwal","reviewCount":290,"yearsInBusiness":10,"itinerariesPublished":34}', '[{"title":"Arrival in Hanoi, Hoan Kiem Lake & Old Quarter Street Food","evening":"Savor famous Vietnamese Egg Coffee (Ca Phe Trung) and authentic steaming Pho noodle soup; Water Puppet Show.","morning":"Land at Noi Bai International Airport (HAN); private transfer to boutique French colonial hotel.","afternoon":"Stroll around tranquil Hoan Kiem Lake, Ngoc Son Temple, and take a traditional electric cyclo ride through 36 guild streets.","dayNumber":1,"highlights":["Private Airport Pickup","Hoan Kiem Lake Walk","Egg Coffee & Water Puppet Show"]},{"title":"Hanoi to Halong Bay: Luxury Overnight Cruise & Sung Sot Cave","evening":"Sunset cocktail party on sun deck; night squid fishing; 5-course seafood gourmet dinner under the stars.","morning":"Express limousine drive from Hanoi to Halong Bay marina; board luxury wooden junk ship cruise.","afternoon":"Cruise past thousands of towering limestone emerald islands; explore giant Sung Sot (Surprise) Cave.","dayNumber":2,"highlights":["Halong Bay Luxury Cruise","Sung Sot Limestone Cave","Sunset Deck Cocktails & Squid Fishing"]},{"title":"Halong Bay Kayaking, Flight to Da Nang & Lantern Town Hoi An","evening":"Stroll through glowing lantern-lit UNESCO Old Town; take a wishing candle wooden boat ride on Hoai River.","morning":"Sunrise Tai Chi on deck; kayak through tranquil Luon Cave surrounded by monkeys.","afternoon":"Disembark cruise; transfer to airport for short 1-hour flight to Da Nang; drive to ancient Hoi An.","dayNumber":3,"highlights":["Sunrise Tai Chi & Kayak","Hoi An Lantern Town","Hoai River Candle Boat"]},{"title":"Bana Hills Golden Bridge & Coconut Basket Boat Ride","evening":"Dinner at riverside restaurant in Hoi An; sample Cao Lau noodles and White Rose dumplings.","morning":"Take world-record cable car to Ba Na Hills; walk across iconic giant stone hands Golden Bridge in the clouds.","afternoon":"Visit Cam Thanh coconut water village; ride spinning round bamboo basket boats with local fishermen.","dayNumber":4,"highlights":["Ba Na Hills Golden Bridge","Spinning Bamboo Basket Boat","Hoi An Gourmet Cuisine"]},{"title":"An Bang Beach, Custom Tailoring & Cooking Class","evening":"Night market exploration; souvenir silk lanterns and Vietnamese ground coffee beans.","morning":"Relax at pristine An Bang white sand beach or take a 2-hour custom tailoring suit/dress fitting.","afternoon":"Hands-on Vietnamese cooking class making crispy Banh Xeo pancakes and fresh spring rolls.","dayNumber":5,"highlights":["An Bang Beachfront","Custom Silk Tailoring","Authentic Cooking Class"]},{"title":"Da Nang Marble Mountains & Airport Departure","evening":"Transfer to Da Nang International Airport (DAD) for homeward flight.","morning":"Visit dramatic Marble Mountains caves and Dragon Bridge in Da Nang.","afternoon":"Last-minute souvenir shopping for Cashews and Marou dark chocolate.","dayNumber":6,"highlights":["Marble Mountains Caves","Dragon Bridge Landmark","Smooth Flight Connection"]}]', '[{"name":"Hanoi Pearl Hotel / La Siesta Hoi An","tier":"Budget","perks":["Old Quarter Location","Free Breakfast"],"rating":4.5,"estPricePerNight":"₹3,500"},{"name":"Mon Chéri Halong Cruise / Anantara Hoi An Resort","tier":"Comfort","perks":["Balcony Ocean Cruise","Riverfront Pool"],"rating":4.88,"estPricePerNight":"₹14,000"},{"name":"Capella Hanoi / Four Seasons Resort The Nam Hai","tier":"Luxury","perks":["Michelin Dining","Private Beach Villa","Butler"],"rating":4.98,"estPricePerNight":"₹42,000"}]', '{"flights":21000,"foodDining":5000,"accommodation":12000,"localTransport":2000,"activitiesSightseeing":4000}', '["Vietnam eVisa step-by-step fast approval guidance ($25 official fee)","Verified Halong Bay cruise operator direct discount links","Hoi An 24-hour express tailor recommendations"]', '["International and domestic flights","Personal tailor garments and shopping"]', '2026-09-21 22:15:18');
