-- ==============================================================================
-- 1. Table structure for `orders`
-- ==============================================================================

DROP TABLE IF EXISTS `orders`;
CREATE TABLE `orders` (
  `order_id` varchar(64) NOT NULL,
  `itinerary_id` varchar(64) NOT NULL,
  `itinerary_title` varchar(255) NOT NULL,
  `destination` varchar(100) NOT NULL,
  `customer_name` varchar(120) NOT NULL,
  `customer_email` varchar(160) NOT NULL,
  `customer_mobile` varchar(30) DEFAULT NULL,
  `amount_paid` decimal(10,2) NOT NULL DEFAULT 99.00,
  `payment_method` varchar(60) DEFAULT 'UPI / Razorpay Gateway',
  `razorpay_payment_id` varchar(100) NOT NULL,
  `razorpay_order_id` varchar(100) DEFAULT NULL,
  `status` enum('PAID','PENDING','FAILED') DEFAULT 'PAID',
  `email_sent` tinyint(1) DEFAULT 0,
  `email_sent_to` varchar(160) DEFAULT NULL,
  `agent_name` varchar(120) DEFAULT NULL,
  `agent_phone` varchar(40) DEFAULT NULL,
  `agent_email` varchar(160) DEFAULT NULL,
  `agent_whatsapp` varchar(40) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`order_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

